<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\ValueObject\Accessor\SmtpOutboundConfigTenantAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the SmtpOutboundConfigTenantAccessor trait.
 *
 * Covers null default, string/VO assignment via withTenant,
 * getTenant/tenant accessors, and isTenantChanged with/without original.
 */
class SmtpOutboundConfigTenantAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withTenant creates a new instance with the Tenant set
     * from a string value, and getTenant returns the primitive string.
     */
    public function testWithTenantFromString(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigTenantAccessorUnitTest();

        // Act
        $result = $holder->withTenant(new TenantRef('one'));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new TenantRef('one'), $result->getTenant());
    }
    /**
     * Asserts that withtenant has access to the value object
     * from a string value, and getTenant returns the primitive string.
     */
    public function testWithTenantFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigTenantAccessorUnitTest();

        // Act
        $result = $holder->withTenant(new TenantRef('one'));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new TenantRef('one'), $result->tenant()->value());
    }
    public function testChangedTenant(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigTenantAccessorUnitTest();
        $original = $holder->withTenant( new TenantRef('one'));
        $same = $holder->withTenant( new TenantRef('one'));
        $modified = $holder->withTenant(new TenantRef('other'));

        // Act
        $unchanged = $holder->isTenantChanged();
        $withSame = $original->isTenantChanged( $same );
        $withDiferent = $original->isTenantChanged( $modified );

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithSmtpOutboundConfigTenantAccessorUnitTest
{
  use SmtpOutboundConfigTenantAccessor;
}
